              && self.pages.value()[0].block_size == 8
              && self.pages.value()[BIN_FULL as int].block_size ==
                    8 * (524288 + 2)

              && self.pages_free_direct.value()@.len() == PAGES_DIRECT
              && self.pages.value()@.len() == BIN_FULL + 1
        }
