pub fn check_is_good(
    &self,
    Tracked(thread_tok): Tracked<&Mim::thread_local_state>,
    Tracked(tok): Tracked<Mim::thread_checked_state>,
) -> (new_tok: Tracked<Mim::thread_checked_state>)
    requires self.wf(), !self.is_empty(),
